import sys
from pathlib import Path
from typing import TYPE_CHECKING

sys.path.insert(0, str(Path(__file__).parent / "vendor"))
if TYPE_CHECKING:
    from vendor import report_backend
else:
    import report_backend


def render_report() -> str:
    return report_backend.render()

import yaml


def read_document(text: str) -> object:
    loader = yaml.SafeLoader(text)
    try:
        return loader.get_single_data()
    finally:
        loader.dispose()

from __future__ import annotations

import importlib.util
import json
from pathlib import Path
import subprocess
import sys

import pytest
import yaml

ROOT = Path(__file__).resolve().parent.parent
PROJECT = ROOT / 'project'
BASELINE = ROOT / 'scratch' / 'baseline'


def load(root: Path, name: str):
    spec = importlib.util.spec_from_file_location(name + '_' + root.name, root / (name + '.py'))
    assert spec is not None and spec.loader is not None
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


@pytest.mark.parametrize('value', [None, 0, False, '', [], {}, object()])
def test_cast_identity_and_differential(value):
    assert load(BASELINE, 'cast_target').read_value(value) is value
    assert load(PROJECT, 'cast_target').read_value(value) is value


@pytest.mark.parametrize('text', ['', 'null', '0', 'false', '[]', '{}', 'name: example\nitems: [1, 2, 10]', '"line\\nquote\\"colon:---"'])
def test_yaml_valid_differential(text):
    original = load(BASELINE, 'yaml_target').read_document(text)
    candidate = load(PROJECT, 'yaml_target').read_document(text)
    assert candidate == original
    assert type(candidate) is type(original)


@pytest.mark.parametrize('text', ['[unterminated', '---\na: 1\n---\nb: 2', '!!python/object/apply:os.system ["echo unsafe"]'])
def test_yaml_rejection_differential(text):
    errors = []
    for root in [BASELINE, PROJECT]:
        with pytest.raises(yaml.YAMLError) as caught:
            load(root, 'yaml_target').read_document(text)
        errors.append(type(caught.value))
    assert errors[0] is errors[1]


@pytest.mark.parametrize('root', [BASELINE, PROJECT])
@pytest.mark.parametrize('fail', [False, True])
def test_yaml_dispose_on_success_and_error(root, fail, monkeypatch):
    events = []
    class Loader:
        def __init__(self, text):
            assert text == 'input'
        def get_single_data(self):
            if fail:
                raise ValueError('expected parse failure')
            return {'safe': 0}
        def dispose(self):
            events.append('disposed')
    module = load(root, 'yaml_target')
    monkeypatch.setattr(module.yaml, 'SafeLoader', Loader)
    if fail:
        with pytest.raises(ValueError, match='expected parse failure'):
            module.read_document('input')
    else:
        assert module.read_document('input') == {'safe': 0}
    assert events == ['disposed']


def test_real_disposal_return_annotation():
    loader = yaml.SafeLoader('0')
    assert loader.get_single_data() == 0
    assert loader.dispose() is None


def test_import_from_unrelated_cwd_and_side_effect_differential():
    results = []
    for root in [BASELINE, PROJECT]:
        program = 'import sys, json; from pathlib import Path; sys.path.insert(0, sys.argv[1]); import import_target as target; print(json.dumps([target.render_report(), Path(sys.path[0]).as_posix() == sys.argv[1] + "/vendor", Path(target.report_backend.__file__).as_posix().endswith("/vendor/report_backend.py")]))'
        completed = subprocess.run([sys.executable, '-c', program, root.as_posix()], cwd=ROOT / 'scratch', capture_output=True, text=True, check=True, timeout=10)
        assert completed.stderr == ''
        results.append(json.loads(completed.stdout))
    assert results == [['ok', True, True], ['ok', True, True]]


def test_original_and_split_assertion():
    assert load(BASELINE, 'test_assertion').test_command() is None
    assert load(PROJECT, 'test_assertion').test_command() is None
